int maxWater(vector<int>& arr) {
    int n = arr.size();

    // left[i] contains height of tallest bar to the
    // left of i'th bar including itself
    vector<int> left(n);

    // right[i] contains height of tallest bar to
    // the right of i'th bar including itself
    vector<int> right(n);

